html:
{% set company_doc = frappe.db.get_value("Company", doc.company, ["company_logo", "email", "phone_no"], as_dict=1) if doc.company else {} %}
{% set customer_doc = frappe.db.get_value("Customer", doc.applicant, ["customer_name", "dealer_license_no"], as_dict=1) if doc.applicant else {} %}
{% set hbr = frappe.db.get_value("Home Build Request", doc.home_build_request, ["factory", "floor_plan", "home_buyer", "end_buyer_name"], as_dict=1) if doc.home_build_request else {} %}
{% set manufacturer_name = frappe.db.get_value("Supplier", hbr.factory, "supplier_name") if hbr and hbr.factory else "" %}
{% set buyer_name = frappe.db.get_value("Customer", hbr.home_buyer, "customer_name") if hbr and hbr.home_buyer else ((hbr.end_buyer_name or doc.buyer_name or "") if hbr else (doc.buyer_name or "")) %}

{% set _addr_link = frappe.db.get_value("Dynamic Link", {"link_doctype": "Customer", "link_name": doc.applicant, "parenttype": "Address"}, "parent") %}
{% set _addr = frappe.db.get_value("Address", _addr_link, ["address_line1", "city", "state", "pincode"], as_dict=1) if _addr_link else {} %}
{% set _contact_link = frappe.db.get_value("Dynamic Link", {"link_doctype": "Customer", "link_name": doc.applicant, "parenttype": "Contact"}, "parent") %}
{% set _contact = frappe.db.get_value("Contact", _contact_link, ["first_name", "last_name", "phone", "mobile_no", "email_id"], as_dict=1) if _contact_link else {} %}

{%- macro format_currency(amount) -%}
{{ frappe.utils.fmt_money(amount, currency="USD") }}
{%- endmacro -%}

{%- macro fmt_date(d) -%}
{%- if d -%}{{ frappe.utils.formatdate(d, "MM/dd/yyyy") }}{%- endif -%}
{%- endmacro -%}

{%- macro format_phone(phone) -%}
{%- if phone -%}
{%- set digits = phone | replace("+", "") | replace("-", "") | replace(" ", "") | replace("(", "") | replace(")", "") -%}
{%- if digits | length == 10 -%}
+1 ({{ digits[:3] }}) {{ digits[3:6] }}-{{ digits[6:] }}
{%- elif digits | length == 11 and digits[0] == '1' -%}
+1 ({{ digits[1:4] }}) {{ digits[4:7] }}-{{ digits[7:] }}
{%- else -%}
{{ phone }}
{%- endif -%}
{%- endif -%}
{%- endmacro -%}

<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">

<style>
  .inv {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif !important;
    font-weight: 500 !important; color: #000 !important;
    font-size: 13px !important; line-height: 1.2 !important; width: 100% !important;
  }
  .inv table { border-collapse: collapse !important; width: 100% !important; }
  .inv td, .inv th { padding: 0 !important; vertical-align: top !important; }
  .inv-div {
    border-top: 1px solid #ddd !important; border-bottom: none !important;
    border-left: none !important; border-right: none !important;
    height: 0 !important; margin: 32px 0 !important; background: none !important;
  }
  .lbl { font-weight: 600 !important; font-size: 13px !important; color: #000 !important; padding-bottom: 6px !important; }
  .val { font-size: 13px !important; font-weight: 500 !important; color: #333b44 !important; line-height: 1.4 !important; }
  .inv-items {
    width: 100% !important; border-collapse: separate !important; border-spacing: 0 !important;
    border-radius: 4px !important; overflow: hidden !important;
  }
  .inv-items thead th {
    background: #000 !important; color: #fff !important; font-weight: 600 !important;
    font-size: 12px !important; padding: 12px 20px !important; text-align: left !important;
    letter-spacing: 0.3px !important; border: none !important;
  }
  .inv-items thead tr th:first-child { border-top-left-radius: 4px !important; }
  .inv-items thead tr th:last-child { border-top-right-radius: 4px !important; }
  @media print { .inv-items thead { display: table-row-group !important; } }
  .inv-items tbody td {
    padding: 12px 20px !important; font-size: 12px !important; font-weight: 500 !important;
    color: #333b44 !important; border-bottom: 1px solid #e0e0e0 !important;
    vertical-align: top !important; background: #f5f5f5 !important;
  }
  .inv-items tbody td.f-lbl { font-weight: 700 !important; color: #000 !important; width: 260px !important; }
  .inv-items tbody td.f-val { font-weight: 500 !important; color: #000 !important; }
  .inv-items tbody tr:last-child td { border-bottom: none !important; }
  .inv-items tbody tr:last-child td:first-child { border-bottom-left-radius: 4px !important; }
  .inv-items tbody tr:last-child td:last-child { border-bottom-right-radius: 4px !important; }
  .legal-text { font-size: 11px !important; line-height: 1.6 !important; color: #333b44 !important; }
  .legal-text ol { padding-left: 20px !important; margin: 12px 0 !important; }
  .legal-text ol li { margin-bottom: 8px !important; }
  .sig-line {
    border-bottom: 1px solid #333 !important; min-width: 280px !important;
    display: inline-block !important; margin-left: 8px !important;
  }
  .no-break { page-break-inside: avoid !important; }
</style>

<div class="inv">

  <!-- ═══ HEADER ═══ -->
  <table>
    <tr>
      <td style="width: 50% !important;">
        <img src="/files/logo.png" style="height: 40px !important; object-fit: contain !important; display: block !important;" alt="Dealer Capital Resources">
      </td>
      <td style="width: 50% !important; text-align: right !important;">
        <div style="font-size: 13px !important; color: #333b44 !important;">{{ doc.name }}</div>
      </td>
    </tr>
  </table>

  <div class="inv-div"></div>

  <!-- ═══ TITLE ═══ -->
  <div style="text-align: center !important; padding-bottom: 24px !important;">
    <div style="font-size: 20px !important; font-weight: 600 !important; color: #000 !important;">EXHIBIT A</div>
    <div style="font-size: 16px !important; font-weight: 600 !important; color: #000 !important; text-decoration: underline !important; padding-top: 8px !important;">RECEIPT</div>
  </div>

  <!-- ═══ PARTIES & HOME DETAILS ═══ -->
  <table class="inv-items">
    <thead>
      <tr><th colspan="2">Loan Details</th></tr>
    </thead>
    <tbody>
      <tr>
        <td class="f-lbl">Dealer</td>
        <td class="f-val">{{ customer_doc.customer_name or '' }}<br>{{ customer_doc.dealer_license_no or '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Lender</td>
        <td class="f-val">Dealer Capital Resources, Inc.<br>A California Corporation<br>CFL 603 I934</td>
      </tr>
      <tr>
        <td class="f-lbl">Financed Home</td>
        <td class="f-val">
          Serial No. {{ doc.home_serial_no or '________' }}<br>
          Quote No. {{ doc.quote_no or '________' }}<br>
          Floor Plan: {{ doc.floor_plan or hbr.floor_plan or '________' }}<br>
          Customer: {{ (buyer_name or '________') | e }}
        </td>
      </tr>
      <tr>
        <td class="f-lbl">Manufacturer</td>
        <td class="f-val">{{ manufacturer_name }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Advance Date</td>
        <td class="f-val">{% if doc.financed_invoice_date %}{{ fmt_date(doc.financed_invoice_date) }} (invoice/funding date; interest begins on this date){% else %}Approximately {{ fmt_date(doc.advance_date_requested) }} (final date is the factory invoice date){% endif %}</td>
      </tr>
      <tr>
        <td class="f-lbl">Advance</td>
        <td class="f-val">{{ format_currency(doc.loan_amount) if doc.loan_amount else '$________' }} {% if doc.financed_invoice %}(purchase invoice total including freight, plus additional financed DCR fees){% else %}(estimate; final invoice and additional financed fees require a final packet){% endif %}</td>
      </tr>
    </tbody>
  </table>

  <div class="inv-div"></div>

  <!-- ═══ LEGAL TEXT ═══ -->
  <div class="legal-text">
    <p>This RECEIPT is executed and delivered by Dealer to Lender pursuant to Dealer's obligations that certain MASTER INVENTORY FINANCING AGREEMENT between Dealer and Lender (the "<strong>Financing Agreement</strong>"). All capitalized terms not defined herein shall have the meanings set forth in the Financing Agreement.</p>

    <p>Dealer acknowledges and certifies as follows:</p>

    <ol>
      {% if doc.financed_invoice_date %}
      <li>As of the above Advance Date, Lender sets aside the above Advance for Dealer's benefit.</li>
      <li>Payment to the Manufacturer may occur after the Advance Date. Interest begins on the Advance Date.</li>
      {% else %}
      <li>The above Advance is an estimate. The final invoice packet will state the Advance Date and amount.</li>
      <li>The final invoice packet is required before funding. Interest begins on the Advance Date stated in that packet.</li>
      {% endif %}
      <li>Such Advance relates to the above identified Financed Home.</li>
      <li>Such Financed Home is and shall be deemed part of the Collateral under the Financing Agreement.</li>
    </ol>
  </div>

  <div class="inv-div"></div>

  <!-- ═══ SIGNATURE ═══ -->
  <div class="no-break">
    <table style="margin-top: 8px !important;">
      <tr>
        <td style="width: 40% !important;">
          <div class="lbl">DEALER</div>
        </td>
        <td style="width: 60% !important;">
          <div class="val" style="font-weight: 600 !important;">{{ customer_doc.customer_name or '' }}</div>
          <div style="padding-top: 20px !important;">
            <div class="lbl">BY: <span style="color: #fff !important; font-size: 1px !important;">/sig1/</span><span class="sig-line">&nbsp;</span></div>
          </div>
          <div style="padding-top: 12px !important;">
            <div class="val">Name: {{ ((_contact.first_name or '') ~ ' ' ~ (_contact.last_name or '')) | trim or '________' }}</div>
          </div>
          <div style="padding-top: 8px !important;">
            <div class="lbl">Title: <span class="sig-line">&nbsp;</span></div>
          </div>
          <div style="padding-top: 8px !important;">
            <div class="val">Address: {{ _addr.address_line1 or '' }}</div>
            <div class="val">{{ (_addr.city or '') ~ ', ' ~ (_addr.state or '') ~ ' ' ~ (_addr.pincode or '') }}</div>
          </div>
        </td>
      </tr>
    </table>
  </div>

  <div class="inv-div"></div>

  <!-- ═══ FOOTER ═══ -->
  <table>
    <tr>
      <td style="width: 50% !important; vertical-align: top !important;">
        <img src="/files/Icon.png" style="height: 25px !important; object-fit: contain !important; display: block !important; filter: brightness(0) !important;" alt="DCR">
      </td>
      <td style="width: 50% !important; text-align: right !important; vertical-align: top !important;">
        <div class="lbl">Contact</div>
        <div class="val">{{ company_doc.email or 'accounting@dealercapital.net' }}</div>
        <div class="val">{{ format_phone(company_doc.phone_no or '8004541116') }}</div>
      </td>
    </tr>
  </table>

  <div style="text-align: center !important; padding-top: 16px !important;">
    <div style="font-size: 9px !important; color: #999 !important;">Version 6 October 9, 2026</div>
  </div>

</div>
